from sqlalchemy import text

TABLES = ("audit_log", "sessions")

def purge(conn, cutoff):
    for (t,) in conn.execute(text("SELECT tablename FROM pg_tables WHERE schemaname = 'public'")):
        conn.execute(text(f'DELETE FROM "{t}" WHERE created_at < :c'), {"c": cutoff})
    for name in TABLES:
        conn.execute(text(f'DELETE FROM "{name}" WHERE created_at < :c'), {"c": cutoff})
    for t in inspector.get_table_names():
        conn.execute(text(f'DELETE FROM "{t}" WHERE created_at < :c'), {"c": cutoff})

