    cur.execute(f"SELECT id, name FROM t WHERE id IN ({ph})", ids)

def search(cur, name, age):
    clauses, args = [], []
    if name:
        clauses.append("name = %s")
        args.append(name)
    if age:
        clauses.append("age = %s")
        args.append(age)
    cur.execute(f"SELECT id, name FROM t WHERE {' AND '.join(clauses)}", args)

