import os, subprocess
OUT = "/tmp/out.tgz"
SRC = "/srv/app"
REPO = "/srv/repo"

def pack():
    os.system(f"tar czf {OUT} {SRC}")
    subprocess.run("git -C " + REPO + " pull", shell=True)

def load():
    for mod in ("json", "csv"):
        exec(f"import {mod}")
    ops = {"add": "a+b", "sub": "a-b"}
    for k in ops:
        eval(f"lambda a, b: {ops[k]}")

